-- wave-ubud-north-east-2026-10-08: 207 field(s) in one DO block, one UPDATE per column.
-- Each UPDATE must change exactly the number of rows it lists; if one does not, the whole block rolls back.
-- Generated 2026-10-08 by scripts/copy/build-copy-sql.mjs. Guards: md5 of the current text; every literal is ASCII.
do $apply$
declare n int;
begin
  update venues v set why_its_here = d.val
  from (values
    ('8lements-spa-saranam', 'f09788168065f2d4a6f34d0cfafc5c4c', 'A rooftop spa at HOMM Saranam in the Bedugul highlands, looking out over rice terraces and mountains. It runs under Banyan Group''s 8LEMENTS wellness brand, with therapists trained at the Banyan Tree Academy. Non-guests are welcome.'),
    ('air-terjun-tegenungan', '38daf74879fc3e0b6873291f6d689f74', 'A big waterfall beside Tegenungan village in Gianyar, about 10 kilometres outside Ubud. It is easy to reach, and steps take you down to the falls.'),
    ('akar-ubud', '020dd01a98f1249d009c43bf4281d75c', 'Akar is a jungle restaurant at Kedisan in Tegallalang, north of Ubud. It does breakfast and dinner, and the setting suits a special occasion.'),
    ('alchemy', 'fce9f5e40276eac08d0e45542efbb1f6', 'Alchemy is a breakfast spot in Penestanan where the whole menu is plant-based and gluten-free. At the raw breakfast bar you choose what goes on your plate, and the prices are clear before you order.'),
    ('alchemy-yoga-and-meditation-center-ubud', '2b623dedee3b5a69a0be34fb7adf1ad4', 'A Penestanan centre for yoga and meditation, with its roots in tantra and Hatha yoga. There is a full timetable of classes every day, plus meditation, sound healing and a weekly ecstatic-dance night. It is affiliated with the Alchemy raw-vegan cafe next door.'),
    ('alchemy-yoga-meditation-center', '1cad7d7fe626957ec9dcfbb57bb2b762', 'This yoga and meditation centre in Penestanan teaches in two bamboo shalas. Drop-in classes run every day across Hatha and Tantra vinyasa, Yin, meditation, ecstatic dance and sound-healing ceremonies. There are multi-class passes and Yoga Alliance teacher trainings at 200hr and 300hr.'),
    ('anomali-coffee-ubud', '5392076d87ee75099518a61432292404', U&'The Jalan Raya Ubud caf\00E9 of Anomali, an Indonesian specialty-coffee roaster founded in Jakarta in 2007 that now has outlets across Indonesia. Its single-origin beans come from all over the archipelago, and the regions on offer rotate.'),
    ('bali-barber-ubud', '483012d946108d1b6b6842d0de398729', 'Bali Barber''s shop in central Ubud, where men can walk in for a cut, beard work or a traditional hot-towel shave.'),
    ('bali-bohemia', 'c09dfa7af96dde545e76038f3136005a', 'A boutique hotel''s restaurant and bakery beside the Sacred Monkey Forest Sanctuary. The cooking is East-Mediterranean in style and leans plant-forward. The bakery also runs on its own, and some evenings have live music.'),
    ('bali-botanica-spa', '9a39b8a0b18da6202d512a3c04dd188b', 'An Ayurvedic day spa on the Sanggingan ridge that looks over jungle and rice fields. It opened in 2006, and in 2024 it was relaunched under Oneworld Ayurveda with Balinese and Ayurvedic treatments and programs.'),
    ('bebek-bengil', '058a21dceb0305c7a27908d403a5d1c6', 'Bebek Bengil is a duck restaurant in Ubud, open since 1990, with dining pavilions in a rice-paddy garden. Its Balinese-style crispy duck is steamed in Indonesian spices, then deep-fried until the skin crackles and the meat stays tender.'),
    ('big-dragon-villas-ubud', 'c66e6320952728554bc97e9cac29f81b', 'A boutique villa property in the rice paddies at Pejeng, near Tampaksiring, opened in 2025. Its 17 rooms and suites sit around an infinity pool, and central Ubud is a short drive away.'),
    ('cafe-wayan-and-bakery', 'ec56952def3a5bb855086fc972a37608', 'Open since 1986 on Monkey Forest Road, this restaurant has a bakery out front and a garden behind that looks over rice paddies. The menu is wide, running across Indonesian, Thai and Italian, and Sunday evenings bring a traditional Balinese buffet.'),
    ('cantika-zest', '1c783e77c9ea5cdff621bf7c3642ea01', 'A jungle spa beside a stream on the edge of Penestanan village. It makes its own organic skincare from garden-sourced ingredients and uses it for massages, facials, scrubs and outdoor flower baths. A garden tour is also an option.'),
    ('casa-luna', 'd3c2e16dce5fd303d0ecfd2fa2a70bbb', 'Food writer Janet DeNeefe opened this restaurant on Jalan Raya Ubud in 1992. The menu moves between Balinese cooking, from nasi campur to ceremonial curries and slow-cooked spice-paste dishes, and a modern Mediterranean side. Pastries come from Honeymoon Bakery, its sister business.'),
    ('cascades', '60050fbf5de3319fcd6a12b422b9cbab', 'Viceroy Bali''s restaurant, also branded as part of CasCades Suites, sits above the Valley of the Kings with jungle views. Central Ubud is about five minutes'' drive away. The kitchen does a Balinese Rijsttafel tasting menu and Western dishes, with produce from its own organic gardens.'),
    ('clear-cafe', '38bd1c5e88cb36d2965b6d09240fdcdd', U&'Healthy, international food with a wellness focus, at a caf\00E9 on Jl. Hanoman in central Ubud.'),
    ('coco-nails-ubud', '59cf6bdfc84ba42a684dd72a1646eb05', 'Manicures, pedicures and nail art at an Ubud nail salon in a central location.'),
    ('como-uma-ubud-fitness', '9aba2dd89bab9c4001a57cf7b53b11ba', 'COMO Uma Ubud''s fitness centre has current cardio and strength machines, with the COMO Shambhala wellness programme behind it. A resident instructor builds private sessions for any level. In the same wellness area are an open-air yoga pavilion, steam rooms and a 25-metre pool.'),
    ('dicarik-warung', 'c363aba6f6960e2df012fdf04bcbf0af', U&'A warung on Jl. Kajeng, on the rice-field walk north of central Ubud, run by a mother-daughter team. The hands-on Balinese cooking class teaches the garden spices, then 7 dishes and 2 drinks. There is \00E0 la carte Balinese food too, such as betutu bebek.'),
    ('donna-ubud', '7aa63e84068c9cb21cdc5cbac04cb961', 'In the middle of Jalan Monkey Forest, Donna is a restaurant, lounge and rooftop bar with a Mediterranean and Latin American menu. It opens daily from late morning until late. Shisha is served after 4pm, and the upstairs becomes a club on Friday nights.'),
    ('four-seasons-resort-bali-at-sayan-fitness', '41066a625bb6be5a14016d1980ca24ed', 'The Fitness Hub at Four Seasons Sayan, high above the Ayung River, is free for resort guests. Beyond the gym there are three private studios with trainers and a reformer pilates studio. The recovery room has an ice bath, a sauna and a steam room.'),
    ('gajah-putih-ubud', 'c2f8b2f88f0913f7da8dd8969e3c1c21', 'An Ubud restaurant whose cooking is billed as modern gourmet cuisine. Its published menu lists 8 priced items, including alcohol, non-alcohol and wine pairings; Pairing Wine Malam is 400K IDR. Booking is on the restaurant''s own website.'),
    ('gelato-secrets-ubud', 'f3aabdc4441e9adb68b8d01b26e269c8', 'Gelato Secrets is an Italian gelato brand that opened its shop in Ubud in 2009. The gelato and sorbetto are made fresh every day from all-natural ingredients. Some flavours are Indonesian-inspired, such as black rice and coconut pandan.'),
    ('heart-space-bali', '0bfc674cb8b6b47ced2efde013aa3650', 'A calm, holistic studio on the corner where Pengosekan meets Nyuh Kuning. It specialises in slower, restorative practice, sound and Balinese healing.'),
    ('hujan-locale', '3f750d46c9df67e7edbbf8df68b22fda', 'Will Meyrick''s modern Indonesian restaurant in central Ubud, in a renovated two-storey building. The bar is downstairs; upstairs, the dining room looks over a temple and the street. The kitchen reworks street-food flavours from Java, Sumatra, Sulawesi and Bali with local ingredients and modern presentation.'),
    ('ibu-rai', '34a8d9c8646acb78bbaa5302c2fd1613', 'Ibu Rai, born in 1925, ran a food stall near Ubud Palace; her family founded this restaurant and gallery on Jalan Monkey Forest. It opened as a restaurant in 1992, and Indonesian specialties share the menu with European dishes in a room full of art.'),
    ('jaens-spa', '1d858d309972ecdc8f3690635681ae34', 'A Balinese spa with several outlets near the Monkey Forest, pitched as ''affordable luxury''. The menu covers Balinese massage, facials, body care and full-day packages with free transport in the Ubud area.'),
    ('karsa-spa', 'e4118e706d2f7eb953b89229cacee5c9', 'An open-air spa in the rice fields at the end of the Campuhan Ridge Walk, founded in 2012. Massage runs from deep-tissue shiatsu to Balinese, Thai and sports styles. Reiki and chakra healing are offered too, and the oils used are organic and Ayurvedic.'),
    ('kojin-teppanyaki-restaurant-ubud-by-wonderspace', 'e94f9ccf49b90e98eabaff1b7fb5822c', 'Named after Kojin, a Japanese god of fire, this restaurant in Kenderan cooks teppanyaki, kaiseki and omakase at the counter. It opens for lunch and dinner.'),
    ('kush-ayurveda-yoga-barn', '08978c1dfe57dd5606a338f35fe94e4e', 'An Ayurvedic spa inside The Yoga Barn, where the therapists assess your dosha first and tailor the treatment to it. Abhyanga, Shirodhara, hot-stone Shila massage and Ayurvedic facials with freshly prepared botanicals are on the list.'),
    ('la-portal-to-shamballah', 'ef40ab4ee81ec053a2db2d8f41ddbac6', 'A vegetarian restaurant and events space in Peliatan, cooking Arabian, Indonesian and Asian dishes with vegan and gluten-free options. The bread is homemade, and the menu runs to Euro-Arabia fusion plates and quesadillas. It also hosts live music and workshops and has private healing rooms.'),
    ('laka-leke', '5b88d70398eb6d0f79ca18d026ff799f', 'Cafe Wayan & Bakery''s sister restaurant, in a garden by the rice fields near Nyuh Kuning and the Monkey Forest. Private dining is in tree-shaded pavilions; craft workshops run in the afternoon. Scheduled evenings bring a Balinese dance show (Kecak/Fire Dance) and a group buffet.'),
    ('locavore-nxt', 'ab7c326f3f83e3b4bbf4b20f4c2c123c', 'The more experimental, ingredient-driven sibling of Locavore, opened in Lodtunduh in December 2023 and led by chefs Eelke Plasmeijer and Ray Adriansyah. This 30-seat tasting-menu room uses only local Indonesian ingredients, cooked with modern European technique.'),
    ('mandapa-spa-ubud', '260d531f7c4144394b8bb60b2685679b', 'The riverside spa at Mandapa, a Ritz-Carlton Reserve on the Ayung river in Kedewatan.'),
    ('mango-tree-spa-loccitane', 'a6e7894a42b7d742a2e7ed2c4f4f3d34', 'A luxury spa at Kupu Kupu Barong Villas in the Ayung River valley, with treatment rooms built into a giant mango tree. The rituals use L''OCCITANE products, and there is a steam room.'),
    ('maya-ubud-spa-ubud', '3047700918cc2872d5b876ba46248d54', 'The wellness side of Maya Ubud Resort & Spa, on the Peliatan ridge. Its riverside spa has treatment pavilions down in the Petanu valley. A yoga shala and a fitness centre look out over the same valley.'),
    ('melting-wok-warung', 'de68e36278ca7cff895f9a19ce12fe0e', 'A French-Laotian couple runs this tiny eight-table warung on Jl. Gootama. The blackboard menu is short and changes daily: coconut curries, stir-fries and crepes. The cooking uses Laotian herbs, and the desserts have French touches.'),
    ('milk-and-madu-ubud', 'a5b9410f8c4bbd46b3bd4596d05ed71c', 'An all-day cafe on Jl. Suweta with a kids menu and group bookings for up to 20. There is a 110K breakfast set.'),
    ('moksa', '258a1042f9c67b49f2fd605044864497', 'A plant-based restaurant in Sayan with a permaculture garden and a farm-to-table kitchen.'),
    ('monkey-bar-bali', '89668501b2be6ebd3044e25984ed0ef2', 'Up in the hills of East Bali, this restaurant and bar is built around an infinity pool at Bella Kita Mountain Retreat. Valley views run toward the sea, and produce comes from the property''s own farm. Entry is pay-and-swim, and it includes credit toward food.'),
    ('mozaic', 'c097b16fcbc77922e48e72e087f1d36d', 'Chef Chris Salans founded this Kedewatan fine-dining restaurant; head chef and co-owner Blake Thornley now leads the kitchen. The cooking applies French technique to Indonesian and Balinese ingredients. There is a multi-course tasting menu and, separately, a Chef''s Table at the live kitchen.'),
    ('norii-japanese-restaurant-ubud', '97b567fcb75beb206e3ebc826de5fdc6', 'Part of the Wonderspace group, this Japanese restaurant in Peliatan serves sushi, wagyu don, wagyu skewers and robatayaki beef. The cocktails lean on yuzu and matcha, with sake too.'),
    ('oneworld-ayurveda', '05d11aca54aee6a40098fc8217eedc30', 'Oneworld Ayurveda runs Panchakarma detox programmes on a palace property in Pengosekan, among jungle and rice fields. Resident Ayurvedic doctors with BAMS qualifications guide each multi-night stay.'),
    ('onion-collective', '3d6b08d22413c667e840e09fd968f750', 'A hotel, restaurant and coworking space on Jl. Raya Pengosekan that has a pool and live music. The menu works for vegans and non-vegans alike, and the place is as much a daytime work spot as somewhere for dinner and drinks.'),
    ('pinstripe-bar-ubud', '3f9286037a9e0e50e9d8ce77d70d51a5', 'A cocktail and wine bar in Ubud that pairs handcrafted drinks with gastro-style bar dining. Booking is by WhatsApp.'),
    ('putri-bali-spa', 'b1010023f171ca72c211bc595affecf5', 'Traditional Balinese massage, body treatments, aromatherapy and flower-bath packages at a day spa on Jl. Raya Sanggingan. Pickup within the Ubud area is free.'),
    ('pyramids-of-chi', '9192fe37a2cf01de2ffc49acd4cdc56b', 'This purpose-built sound-healing venue in the rice fields north of Ubud has two large pyramids for group sound sessions. One of them is scaled to the Great Pyramid of Giza.'),
    ('radiantly-alive', 'feb6b4cef94137ae2dd162933c9d1731', 'A central-Ubud studio for dynamic Vinyasa flows and healing therapies, on Jl. Jembawan. Its teacher trainings draw students from abroad, and a plant-based cafe sits on site.'),
    ('room-4-dessert', 'e833c5988ab073b043761ac7e3cea8ca', 'A dedicated dessert tasting venue on Jl. Raya Sanggingan in Kedewatan, rather than a general restaurant.'),
    ('room4dessert', '17df9870907411cc38e90f76059d935f', 'Chef Will Goldfarb''s dessert-only tasting-menu restaurant in Kedewatan. It sits inside a large botanical garden tied to the recipes themselves. This is a pastry chef''s concept rather than a conventional dinner spot.'),
    ('sacred-river-spa-at-four-seasons-sayan-ubud', '4fd4103435db52a6a8409165c467df73', 'The spa at Four Seasons Resort Bali at Sayan, beside the Ayung river.'),
    ('sakti-dining-room-fivelements-retreat-bali', '2e7ef4c7f9aebb94475ec07a9fada6a7', 'Restaurant in Fivelements Retreat Bali.'),
    ('sang-spa', '829aa73880dfcdc80da721dcaea84cac', 'Established in 2008, this Balinese day spa runs two outlets in central Ubud. Traditional Balinese massage, scrubs, flower baths, reflexology and four-hands massage are on the menu, at affordable prices.'),
    ('sawobali', '6696e1e85275d7f1ad0cec493734a98d', 'A vegan and vegetarian warung and cake shop in Peliatan, with a budget all-you-can-eat buffet of home-style food. The cakes are made in-house, and dishes are cooked without garlic or onion so that Buddhist diners can eat them too.'),
    ('sayuri-healing-food', '53abe4280c42237c7b96909a993b7609', 'A raw-vegan and plant-based cafe in Ubud with a plant-based academy attached. The kitchen leans towards raw, living food rather than standard cooked vegan dishes. There are cold-pressed juices too, and a rotating case of raw desserts.'),
    ('secret-garden-restaurant', '574324d51a8d41336ed00d3daaabb2e7', 'A family-run garden restaurant in Anturan, Lovina. The cooking is Indonesian and Western, with a separate vegetarian menu, and seafood curry and goulash are regulars. Guests staying in Lovina get free pick-up and drop-off.'),
    ('seeds-of-life', '10ed0edb29fa5ef7e46d8fbf2dc73585', 'A 100% raw and vegan restaurant on Jalan Goutama in central Ubud, with a Taoist tonic bar, open since 2014. The dishes are made from fresh, locally grown produce, and Ashtanga yoga classes run upstairs.'),
    ('seniman-coffee-studio', 'ed3d780d4ee1c009200236a3c545fc71', U&'A specialty coffee roaster and caf\00E9 near Ubud Palace that sources and roasts Indonesian origin beans. The coffee is brewed several ways, and the food menu covers Indonesian and Western dishes.'),
    ('shichirin-japanese-restaurant-ubud', '0ceefb64c1b31c4b14a53cc21601cfc5', 'A Japanese grill restaurant on Jl. Bisma. The menu runs from teppanyaki and gyukatsu to izakaya plates. There is sushi and sashimi too.'),
    ('spring-spa-ubud', 'a0557f68a2b8aa0069cc2a912ee63b09', 'A Spring Spa outlet among rice terraces, with treatment rooms that look out over the fields. A dedicated wellness zone holds contrast-therapy plunges, saunas and relaxation lounges.'),
    ('suka-espresso-ubud', 'f1c7571320e3f83d653024e336888972', 'Australian-style breakfast and specialty coffee on Jl. Raya Pengosekan, served from 7:30. Breakfast specials at 60K run until 3pm, and the menu labels vegetarian, vegan and gluten-free dishes clearly.'),
    ('svaha-spa', '912e88f480ed331431c4080c4c3636ed', 'A sustainable, holistic spa group with several outlets around Ubud. The flagship is on Jl. Bisma near the Monkey Forest. Its menu covers Balinese and house massages, body-purification rituals and couples packages.'),
    ('taksu-spa-beauty-ubud', '692f77a30bde510329b1de53d874d009', 'Beauty treatments at Taksu, a healing and spa centre among gardens and koi ponds in central Ubud.'),
    ('taksu-spa-ubud', 'cda5b669d130e390d6eafffaa431fa4c', 'Taksu Spa belongs to the Taksu healing sanctuary in central Ubud, where massage and holistic treatments are given among gardens and water features.'),
    ('taksu-yoga', '1976e730d3c35780ad09a316de4c900b', 'The yoga centre of the Taksu spa and restaurant complex, in a river valley in central Ubud. Classes stay small for individual attention, running daily across beginner, hatha, vinyasa, yin and restorative. There are also private sessions and training courses.'),
    ('taksu-yoga-ubud', '225bc077c4d0a0688034e0736e02123e', 'A wellness centre in a central-Ubud garden on Jl. Goutama Selatan. Small-group yoga classes run alongside an extensive spa, healing and beauty menu.'),
    ('the-elephant', 'c3ed6b12a00d1ef677bf6b61f5a43aae', 'The Elephant is an open-air, 100% vegetarian and vegan restaurant on Jl. Raya Sanggingan. Its elevated terrace looks over Campuhan Ridge, and it serves all day from breakfast through dinner. The sourcing is organic and local, along slow-food lines.'),
    ('the-shala-bali', '659eb8796f6322e4b91df0ebca3360da', 'Built on Balinese and Indian philosophy, The Shala is a boutique yoga property in Sanggingan. Daily yoga comes with Ayurvedic spa treatments, vegetarian dining and rooms on site.'),
    ('the-westin-resort-and-spa-ubud-fitness-studio', '0421674c3e1361849fe21baaecef2890', 'The 24-hour WestinWORKOUT studio at The Westin Ubud in Lodtunduh is free for resort guests. It has cardio and weight machines, free weights and a yoga area, and lends gear to guests travelling light. Morning yoga and meditation run in an open-air pavilion nearby.'),
    ('the-yoga-barn', '709b7a656210036b0089b3f09e1db905', 'A wellness compound on Jl. Raya Pengosekan, with a cluster of open-air shalas and a healing centre. A garden cafe and a shop sit alongside, and dozens of yoga, meditation and sound classes run every day.'),
    ('tukies-coconut-shop', '8561c9074a53578d3968e372246a56d4', 'Everything at this dessert and drinks shop on Jl. Monkey Forest starts with fresh coconut. The vegan coconut ice cream comes in the shell with roasted coconut curls.'),
    ('ubud-beauty-salon', 'e2dc4a560c1da3e66a2d75a4a971244d', 'Hair, nails and basic treatments at a beauty salon in central Ubud.'),
    ('ubud-pilates', '579300be609f041eb3769557c99b36f1', 'A boutique Pilates studio in Ubud with mat and reformer classes.'),
    ('ubud-sari-health-resort', 'ded8809ae1e3e305bee04b649ec6ab0c', 'Minutes from Ubud centre, this health resort has a day spa doing Balinese, Lomi Hawaiian and four-hands massage. It also runs wellness and detox programs and serves raw food.'),
    ('ubud-traditional-spa', '719504d17398036aa31a24c0bca12852', 'A traditional Balinese massage spa in Payogan village, next to Pura Puncak temple. Massage, body scrubs and flower baths are on the menu, and there is free transport to and from central Ubud.'),
    ('ubud-yoga-house', 'ee4514d4cafe2a14184cdeee4b76e64f', 'A boutique yoga studio a little out of the way on Jl. Subak Sokwayah. Classes are small and held in open-air shalas that look over rice terraces and jungle.'),
    ('warung-biah-biah', '7d2591ea31f17ad9fd339c4a4b96cd22', 'A home-style Balinese warung on Jl. Goutama, open since 2002. Nasi campur and local classics come at warung prices, with a house chili sauce and a spread of Balinese sides.'),
    ('warung-siam', 'a89cc66828602d41a093c49ae9c74dea', 'Thai food cooked the traditional way, with fresh herbs, lime and chillies, at a family-run warung on Jl. Goutama. It opened in 2014, and the menu is not westernised.'),
    ('watercress-ubud', 'a87e99ce23ea42fdd39fa1b293e8588d', 'An early-breakfast spot on Jl. Monkey Forest, open from 7am, with breakfast served until 11:30.'),
    ('whos-who', '03517aa60434be5ba9f69ecaf6cdeaed', 'A Belgian bistro on the S-bend in south Ubud, near Jl. Raya Pengosekan. The menu is Belgian comfort classics with Indonesian-influenced touches.'),
    ('zest-ubud', '4540f92453775d65207a040e3a1dc693', 'Zest serves vegan brunch up in the treetops of Penestanan. The whole menu is plant-based, and the savoury dishes are substantial.'),
    ('zuna-yoga-ubud', 'ef87a95baa5ce4524729e18f62c5cad1', 'A dedicated yoga school in Ubud that runs classes and teacher trainings.')
  ) as d(slug, old_md5, val)
  where v.slug = d.slug and v.status = 'active' and v.publication_status = 'published'
    and case when d.old_md5 is null then (v.why_its_here is null or length(trim(v.why_its_here)) = 0) else md5(v.why_its_here) = d.old_md5 end;
  get diagnostics n = row_count; if n <> 83 then raise exception 'wave-ubud-north-east-2026-10-08 why_its_here: expected 83 rows, got %', n; end if;

  update venues v set best_for = d.val
  from (values
    ('8lements-spa-saranam', '6eef10a747ce54dbe4dd0e47cb78045f', 'A highland spa session with a rice-terrace view on a Bedugul or North Bali day trip'),
    ('air-terjun-tegenungan', 'f5cf5758e99cc708f6943558512dd5af', 'A waterfall stop near Ubud for anyone who wants falls without a trek'),
    ('akar-ubud', '2ed7b0b87e59e632406c5f2710e4a071', 'A destination dinner with jungle views'),
    ('alchemy', '9ba1e51fc5bf529e5dcf36ee23616668', 'A plant-based, gluten-free meal, a breakfast after yoga, or laptop time off-peak'),
    ('alchemy-yoga-and-meditation-center-ubud', 'b1550d6ec41996d4f3d2994b95889f16', 'Practitioners drawn to tantra-influenced yoga and community events like ecstatic dance, with a plant-based meal next door'),
    ('alchemy-yoga-meditation-center', 'c920b13bf599cc4597f7133bfafce1d7', 'Drop-in practitioners staying in Ubud or Penestanan who want a varied daily schedule without committing to a retreat'),
    ('anomali-coffee-ubud', '72e0457f828c9d24e92a8b71002ca44b', 'Comparing single origins from Aceh, Bali, Toraja and Java in one sitting, or a casual all-day breakfast'),
    ('bali-barber-ubud', 'dcdf518aefae8d5e560398e54a4579eb', 'A men''s cut or shave in central Ubud without booking ahead'),
    ('bali-bohemia', 'dea07318b0d770d3fc9cd96a0404feef', 'A plant-forward breakfast, bakery pastries, or dinner with live music in a colourful, creative setting'),
    ('bali-botanica-spa', 'c0dcd18c3b3eb6b2f7052fc029d64abd', 'Ayurvedic treatments or a day program on the Sanggingan side of Ubud, with jungle and rice-field views'),
    ('bebek-bengil', '241e665334e9d7c2fd2e5f9c391c96b6', 'A first taste of Balinese crispy duck, or a group dinner of shared regional dishes near the Monkey Forest'),
    ('big-dragon-villas-ubud', '83a791f235608e19f60c76b049f2e8a4', 'A quiet stay away from the centre of Ubud, with views over the pool and rice fields'),
    ('cafe-wayan-and-bakery', '452c8bae16647564f8cf6ea57aaa86ae', 'Groups or families after a garden meal with a broad menu and a dessert to share'),
    ('cantika-zest', '1499c7b6740d7fcc64144d27ad45edd1', 'A treatment with natural, organic products in a quiet Penestanan garden'),
    ('casa-luna', 'f8ec45d6dfa79099ce0ed9ea9ea2dec0', 'A Balinese meal in central Ubud, from breakfast through to dinner'),
    ('cascades', '5f9815d86a45c400e8e3159d31391e09', 'Couples or a small group sitting down to the Indonesian tasting menu with a valley view'),
